+func (it *mergedPostings[T]) Next() bool {
+	for {
+		if !it.h.Next() {
+			return false
+		}
+		// Remove duplicate entries.
+		newItem := it.h.At()
+		if newItem != it.cur {
+			it.cur = newItem
+			return true
+		}
+	}
