+func (it mergedPostings[T]) At() storage.SeriesRef {
+	return it.cur
+}
+
+func (it mergedPostings[T]) Err() error {
+	for _, p := range it.p {
+		if err := p.Err(); err != nil {
+			return err
+		}
+	}
+	return nil
