+}
+
+func (rp *removedPostings) At() storage.SeriesRef {
+	return rp.cur
+}
+
+func (rp *removedPostings) Next() bool {
+	if !rp.initialized {
+		rp.fok = rp.full.Next()
+		rp.rok = rp.remove.Next()
+		rp.initialized = true
+	}
+	for {
+		if !rp.fok {
+			return false
+		}
+
+		if !rp.rok {
+			rp.cur = rp.full.At()
+			rp.fok = rp.full.Next()
+			return true
+		}
+		switch fcur, rcur := rp.full.At(), rp.remove.At(); {
+		case fcur < rcur:
+			rp.cur = fcur
+			rp.fok = rp.full.Next()
