+// createTimeseriesMapByTagSetSingle creates a map for a single side only.
+// This is more efficient when we only need one side's map.
+func createTimeseriesMapByTagSetSingle(be *metricsql.BinaryOpExpr, arg []*timeseries) map[string][]*timeseries {
+	groupTags := be.GroupModifier.Args
+	groupOp := strings.ToLower(be.GroupModifier.Op)
+	if len(groupOp) == 0 {
+		groupOp = "ignoring"
+	}
+	bb := bbPool.Get()
+	m := make(map[string][]*timeseries, len(arg))
+	mn := storage.GetMetricName()
+	for _, ts := range arg {
+		mn.CopyFrom(&ts.MetricName)
+		if !be.KeepMetricNames {
+			mn.ResetMetricGroup()
+		}
+		switch groupOp {
+		case "on":
+			mn.RemoveTagsOn(groupTags)
+		case "ignoring":
+			mn.RemoveTagsIgnoring(groupTags)
+		default:
+			logger.Panicf("BUG: unexpected binary op modifier %q", groupOp)
+		}
+		bb.B = marshalMetricNameSorted(bb.B[:0], mn)
+		k := string(bb.B)
+		m[k] = append(m[k], ts)
+	}
+	storage.PutMetricName(mn)
+	bbPool.Put(bb)
+	return m
+}
